def min_distance(a, b):
    def f(i, j):               # edits to turn a[:i] into b[:j]
        if i == 0:
            return j
        if j == 0:
            return i
        if a[i - 1] == b[j - 1]:
            return f(i - 1, j - 1)
        return 1 + min(f(i - 1, j - 1), f(i - 1, j), f(i, j - 1))
    return f(len(a), len(b))

